window.M3_BANK = {"meta": {"count": 35, "topics": {"3.01": {"en": "Electron theory", "el": "Θεωρία ηλεκτρονίων"}, "3.02": {"en": "Static electricity and conduction", "el": "Στατικός ηλεκτρισμός και αγωγή"}, "3.03": {"en": "Electrical terminology", "el": "Ηλεκτρική ορολογία"}, "3.04": {"en": "Generation of electricity", "el": "Παραγωγή ηλεκτρισμού"}, "3.05": {"en": "DC sources of electricity", "el": "Πηγές DC"}, "3.06": {"en": "DC circuits", "el": "Κυκλώματα DC"}, "3.07": {"en": "Resistance / resistor", "el": "Αντίσταση / αντιστάτης"}, "3.08": {"en": "Power", "el": "Ισχύς"}, "3.09": {"en": "Capacitance / capacitor", "el": "Χωρητικότητα / πυκνωτής"}, "3.10": {"en": "Magnetism", "el": "Μαγνητισμός"}, "3.11": {"en": "Inductance / inductor", "el": "Αυτεπαγωγή / πηνίο"}, "3.12": {"en": "DC motor / generator theory", "el": "Κινητήρες και γεννήτριες DC"}, "3.13": {"en": "AC theory", "el": "Θεωρία AC"}, "3.14": {"en": "R, C and L circuits", "el": "Κυκλώματα R, C, L"}, "3.15": {"en": "Transformers", "el": "Μετασχηματιστές"}, "3.16": {"en": "Filters", "el": "Φίλτρα"}, "3.17": {"en": "AC generators", "el": "Γεννήτριες AC"}, "3.18": {"en": "AC motors", "el": "Κινητήρες AC"}}, "exam": {"options": 3, "pass_mark": 0.75}}, "misc": {"octet_mixup": {"en": "8 is the limit of the second shell. Use 2n² with n = 3.", "el": "Το 8 είναι το όριο της δεύτερης στιβάδας. Χρησιμοποίησε 2n² με n = 3."}, "wrong_n": {"en": "Check which shell: n = 1, 2, 3 … then apply 2n².", "el": "Έλεγξε ποια στιβάδα: n = 1, 2, 3 … και μετά 2n²."}, "forgot_square": {"en": "The n is squared: 2n², not 2n.", "el": "Το n είναι στο τετράγωνο: 2n², όχι 2n."}, "ion_sign": {"en": "Losing negative electrons makes the atom positive (cation); gaining them makes it negative (anion).", "el": "Χάνοντας αρνητικά ηλεκτρόνια το άτομο γίνεται θετικό (κατιόν)· κερδίζοντας γίνεται αρνητικό (ανιόν)."}, "isotope_mixup": {"en": "Isotopes differ in neutrons, not electrons.", "el": "Τα ισότοπα διαφέρουν στα νετρόνια, όχι στα ηλεκτρόνια."}, "neutral_mixup": {"en": "A neutral atom has equal numbers of protons and electrons.", "el": "Ουδέτερο άτομο: ίσος αριθμός πρωτονίων και ηλεκτρονίων."}, "electron_mass": {"en": "Electrons are about 1/1836 of a proton's mass: they hardly count in the atom's mass.", "el": "Το ηλεκτρόνιο έχει περίπου το 1/1836 της μάζας του πρωτονίου: σχεδόν δεν μετράει στη μάζα του ατόμου."}, "coulomb_mixup": {"en": "6.24 × 10¹⁸ is the number of electrons in one coulomb, not a mass ratio.", "el": "Το 6,24 × 10¹⁸ είναι τα ηλεκτρόνια σε ένα coulomb, όχι λόγος μαζών."}, "full_shell": {"en": "A full outer shell holds its electrons tightly: that makes an insulator.", "el": "Πλήρης εξωτερική στιβάδα κρατά σφιχτά τα ηλεκτρόνια: αυτό κάνει έναν μονωτή."}, "neutron_mixup": {"en": "Neutrons carry no charge and do not carry current.", "el": "Τα νετρόνια δεν έχουν φορτίο και δεν μεταφέρουν ρεύμα."}, "ion_breakdown": {"en": "Ionization is any gain or loss of electrons; breakdown is the failure of an insulator in a strong field.", "el": "Ιοντισμός είναι κάθε κέρδος ή απώλεια ηλεκτρονίων· διάσπαση είναι η αστοχία μονωτή σε ισχυρό πεδίο."}, "atom_molecule": {"en": "A single atom of hydrogen or oxygen is not water.", "el": "Ένα άτομο υδρογόνου ή οξυγόνου δεν είναι νερό."}, "element_mixup": {"en": "Water is a compound of two elements, not an element.", "el": "Το νερό είναι ένωση δύο στοιχείων, όχι στοιχείο."}, "inner_shell": {"en": "Inner electrons are tightly bound and take no part in bonding.", "el": "Τα εσωτερικά ηλεκτρόνια είναι σφιχτά δεμένα και δεν συμμετέχουν στους δεσμούς."}, "nucleus_mixup": {"en": "There are no electrons in the nucleus: only protons and neutrons.", "el": "Στον πυρήνα δεν υπάρχουν ηλεκτρόνια: μόνο πρωτόνια και νετρόνια."}, "mass_weight": {"en": "kg is mass. Weight is a force, in newtons: W = m × g.", "el": "Τα kg είναι μάζα. Το βάρος είναι δύναμη, σε newton: W = m × g."}, "divided_g": {"en": "Multiply by g, do not divide.", "el": "Πολλαπλασίασε με το g, μη διαιρείς."}, "static_dynamic": {"en": "Charges flowing are dynamic electricity; static means charges at rest on a surface.", "el": "Φορτία σε ροή είναι δυναμικός ηλεκτρισμός· στατικός σημαίνει φορτία σε ηρεμία σε μια επιφάνεια."}, "conductor_leaks": {"en": "A conductor or a grounded surface lets the charge flow away, so nothing builds up.", "el": "Ένας αγωγός ή μια γειωμένη επιφάνεια αφήνει το φορτίο να φύγει, οπότε δεν συσσωρεύεται."}, "conservation": {"en": "Charge is conserved: what one material loses, the other gains.", "el": "Το φορτίο διατηρείται: ό,τι χάνει το ένα υλικό, το κερδίζει το άλλο."}, "like_unlike": {"en": "Like charges repel, unlike charges attract.", "el": "Ομώνυμα απωθούνται, ετερώνυμα έλκονται."}, "test_charge": {"en": "The convention uses a positive test charge. An electron moves against the field lines.", "el": "Η σύμβαση χρησιμοποιεί θετικό δοκιμαστικό φορτίο. Το ηλεκτρόνιο κινείται αντίθετα στις γραμμές."}, "field_strength": {"en": "Field strength is shown by how close the lines are, not by their length or arrows.", "el": "Η ένταση φαίνεται από την πυκνότητα των γραμμών, όχι από το μήκος ή τα βέλη."}, "outer_surface": {"en": "Excess charge on a conductor goes to the outer surface only.", "el": "Το επιπλέον φορτίο σε αγωγό πηγαίνει μόνο στην εξωτερική επιφάνεια."}, "sharp_points": {"en": "Charge concentrates where the curvature is tightest: at points and edges.", "el": "Το φορτίο συγκεντρώνεται όπου η καμπυλότητα είναι πιο έντονη: σε αιχμές και ακμές."}, "contact_induction": {"en": "Contact gives the same sign as the rod; induction with grounding gives the opposite sign.", "el": "Η επαφή δίνει το ίδιο πρόσημο με τη ράβδο· η επαγωγή με γείωση δίνει το αντίθετο."}, "ground_order": {"en": "If the ground is removed before the rod, the bar keeps its charge.", "el": "Αν η γείωση αφαιρεθεί πριν από τη ράβδο, η ράβδος κρατά το φορτίο της."}, "elementary_charge": {"en": "One electron carries only 1.6 × 10⁻¹⁹ C. A coulomb is 6.24 × 10¹⁸ electrons.", "el": "Ένα ηλεκτρόνιο έχει μόνο 1,6 × 10⁻¹⁹ C. Ένα coulomb είναι 6,24 × 10¹⁸ ηλεκτρόνια."}, "ohm_mixup": {"en": "Volts and ohms give a current (Ohm's law), not a charge. Charge = current × time.", "el": "Volt και ohm δίνουν ρεύμα (νόμος του Ohm), όχι φορτίο. Φορτίο = ρεύμα × χρόνος."}, "forgot_current": {"en": "That is the number for 1 C. Here Q = I × t = 2 C.", "el": "Αυτός είναι ο αριθμός για 1 C. Εδώ Q = I × t = 2 C."}, "inverted_e": {"en": "That is a charge in coulombs, not a number of electrons. Divide Q by e.", "el": "Αυτό είναι φορτίο σε coulomb, όχι αριθμός ηλεκτρονίων. Διαίρεσε το Q με το e."}, "forgot_square_d": {"en": "The distance is squared in Coulomb's law: F ∝ 1/d².", "el": "Η απόσταση είναι στο τετράγωνο στον νόμο του Coulomb: F ∝ 1/d²."}, "inverse_mixup": {"en": "Force goes up with the charges and down with the distance.", "el": "Η δύναμη αυξάνει με τα φορτία και μειώνεται με την απόσταση."}, "one_charge": {"en": "Both charges changed: multiply both factors, 2 × 2.", "el": "Άλλαξαν και τα δύο φορτία: πολλαπλασίασε και τους δύο παράγοντες, 2 × 2."}, "prefix_error": {"en": "Check the prefixes: µ = 10⁻⁶, m = 10⁻³.", "el": "Έλεγξε τα προθέματα: µ = 10⁻⁶, m = 10⁻³."}, "esd_pins": {"en": "Touching connector pins is exactly how ESD damage happens.", "el": "Το άγγιγμα των ακίδων είναι ακριβώς ο τρόπος που γίνεται η ζημιά από ESD."}, "esd_carpet": {"en": "Carpet builds up static charge: a known ESD source.", "el": "Η μοκέτα φορτίζεται στατικά: γνωστή πηγή ESD."}, "fuel_conductor": {"en": "Fuel is a poor conductor; that is why charge builds up in it.", "el": "Το καύσιμο είναι κακός αγωγός· γι' αυτό φορτίζεται."}, "metal_liquid": {"en": "Free electrons carry current in metals. In electrolytes the carriers are ions.", "el": "Τα ελεύθερα ηλεκτρόνια άγουν στα μέταλλα. Στους ηλεκτρολύτες φορείς είναι τα ιόντα."}, "nucleus_carrier": {"en": "Protons stay inside the nuclei; they are never free carriers here.", "el": "Τα πρωτόνια μένουν μέσα στους πυρήνες· δεν είναι ελεύθεροι φορείς."}, "gas_conductor": {"en": "Gases have almost no free carriers until they are ionized.", "el": "Τα αέρια σχεδόν δεν έχουν ελεύθερους φορείς μέχρι να ιονιστούν."}, "vacuum_ions": {"en": "There is nothing in a vacuum to ionize or cool; the electrons must be injected.", "el": "Στο κενό δεν υπάρχει τίποτα να ιονιστεί ή να ψυχθεί· τα ηλεκτρόνια πρέπει να εισαχθούν."}}, "questions": [{"id": "L01-shell3", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "The maximum number of electrons in the third shell (n = 3) is:", "el": "Ο μέγιστος αριθμός ηλεκτρονίων στην τρίτη στιβάδα (n = 3) είναι:"}, "o": [{"en": "8", "el": "8"}, {"en": "18", "el": "18"}, {"en": "32", "el": "32"}], "a": 1, "tags": ["octet_mixup", null, "wrong_n"], "x": {"en": "Capacity = 2n² = 2 × 3² = 18.", "el": "Χωρητικότητα = 2n² = 2 × 3² = 18."}, "status": "new"}, {"id": "L01-shell2", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "The maximum number of electrons in the second shell is:", "el": "Ο μέγιστος αριθμός ηλεκτρονίων στη δεύτερη στιβάδα είναι:"}, "o": [{"en": "2", "el": "2"}, {"en": "4", "el": "4"}, {"en": "8", "el": "8"}], "a": 2, "tags": ["wrong_n", "forgot_square", null], "x": {"en": "2n² = 2 × 2² = 8.", "el": "2n² = 2 × 2² = 8."}, "status": "new"}, {"id": "L01-cation", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "An atom that has lost an electron is called:", "el": "Ένα άτομο που έχασε ένα ηλεκτρόνιο λέγεται:"}, "o": [{"en": "an anion", "el": "ανιόν"}, {"en": "a cation", "el": "κατιόν"}, {"en": "an isotope", "el": "ισότοπο"}], "a": 1, "tags": ["ion_sign", null, "isotope_mixup"], "x": {"en": "Losing an electron leaves more protons than electrons: a positive ion, or cation.", "el": "Με την απώλεια ηλεκτρονίου μένουν περισσότερα πρωτόνια: θετικό ιόν, δηλαδή κατιόν."}, "status": "new"}, {"id": "L01-anion", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "An atom that has gained an extra electron becomes:", "el": "Ένα άτομο που κέρδισε ένα επιπλέον ηλεκτρόνιο γίνεται:"}, "o": [{"en": "a negative ion", "el": "αρνητικό ιόν"}, {"en": "a positive ion", "el": "θετικό ιόν"}, {"en": "a neutral atom", "el": "ουδέτερο άτομο"}], "a": 0, "tags": [null, "ion_sign", "neutral_mixup"], "x": {"en": "More electrons than protons gives a net negative charge: a negative ion (anion).", "el": "Περισσότερα ηλεκτρόνια από πρωτόνια σημαίνει αρνητικό φορτίο: αρνητικό ιόν (ανιόν)."}, "status": "new"}, {"id": "L01-mass", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "The mass of an atom is determined mainly by its:", "el": "Η μάζα ενός ατόμου καθορίζεται κυρίως από:"}, "o": [{"en": "electrons", "el": "τα ηλεκτρόνια"}, {"en": "protons and neutrons", "el": "τα πρωτόνια και τα νετρόνια"}, {"en": "valence electrons", "el": "τα ηλεκτρόνια σθένους"}], "a": 1, "tags": ["electron_mass", null, "electron_mass"], "x": {"en": "A proton is about 1836 times heavier than an electron, and the neutron has about the same mass as the proton.", "el": "Το πρωτόνιο είναι περίπου 1836 φορές βαρύτερο από το ηλεκτρόνιο και το νετρόνιο έχει περίπου ίδια μάζα με το πρωτόνιο."}, "status": "new"}, {"id": "L01-ratio", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "The mass of a proton is approximately how many times the mass of an electron?", "el": "Η μάζα του πρωτονίου είναι περίπου πόσες φορές η μάζα του ηλεκτρονίου;"}, "o": [{"en": "18", "el": "18"}, {"en": "1836", "el": "1836"}, {"en": "6.24 × 10¹⁸", "el": "6,24 × 10¹⁸"}], "a": 1, "tags": [null, null, "coulomb_mixup"], "x": {"en": "m_p / m_e ≈ 1836.", "el": "m_p / m_e ≈ 1836."}, "status": "new"}, {"id": "L01-copper", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "Copper is a good conductor because each atom has:", "el": "Ο χαλκός είναι καλός αγωγός επειδή κάθε άτομο έχει:"}, "o": [{"en": "one loosely bound valence electron", "el": "ένα χαλαρά δεμένο ηλεκτρόνιο σθένους"}, {"en": "a full outer shell", "el": "πλήρη εξωτερική στιβάδα"}, {"en": "more neutrons than protons", "el": "περισσότερα νετρόνια από πρωτόνια"}], "a": 0, "tags": [null, "full_shell", "neutron_mixup"], "x": {"en": "Copper (like silver and gold) has one electron in its outer shell, easily freed to carry current.", "el": "Ο χαλκός (όπως ο άργυρος και ο χρυσός) έχει ένα ηλεκτρόνιο στην εξωτερική στιβάδα, που ελευθερώνεται εύκολα και μεταφέρει ρεύμα."}, "status": "new"}, {"id": "L01-semi", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "Silicon and germanium are classed as:", "el": "Το πυρίτιο και το γερμάνιο κατατάσσονται στους:"}, "o": [{"en": "insulators", "el": "μονωτές"}, {"en": "conductors", "el": "αγωγούς"}, {"en": "semiconductors", "el": "ημιαγωγούς"}], "a": 2, "tags": [null, null, null], "x": {"en": "They sit between conductors and insulators and are used to make transistors and integrated circuits.", "el": "Βρίσκονται ανάμεσα σε αγωγούς και μονωτές και χρησιμοποιούνται σε τρανζίστορ και ολοκληρωμένα."}, "status": "new"}, {"id": "L01-breakdown", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "When an insulator is placed in an extremely strong electric field and its outer electrons are torn loose, this is called:", "el": "Όταν ένας μονωτής βρεθεί σε πολύ ισχυρό ηλεκτρικό πεδίο και αποσπαστούν τα εξωτερικά του ηλεκτρόνια, το φαινόμενο λέγεται:"}, "o": [{"en": "ionization", "el": "ιοντισμός"}, {"en": "breakdown", "el": "διάσπαση (breakdown)"}, {"en": "saturation", "el": "κόρος"}], "a": 1, "tags": ["ion_breakdown", null, null], "x": {"en": "Breakdown: the insulator starts to conduct, usually with physical damage.", "el": "Διάσπαση: ο μονωτής αρχίζει να άγει, συνήθως με φυσική ζημιά."}, "status": "new"}, {"id": "L01-molecule", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "The smallest particle of water that still keeps the properties of water is:", "el": "Το μικρότερο σωματίδιο νερού που διατηρεί τις ιδιότητες του νερού είναι:"}, "o": [{"en": "an atom", "el": "το άτομο"}, {"en": "a molecule", "el": "το μόριο"}, {"en": "an element", "el": "το στοιχείο"}], "a": 1, "tags": ["atom_molecule", null, "element_mixup"], "x": {"en": "A molecule (H₂O: two hydrogen atoms and one oxygen atom). Splitting it gives hydrogen and oxygen, no longer water.", "el": "Το μόριο (H₂O: δύο άτομα υδρογόνου και ένα οξυγόνου). Αν διασπαστεί, παίρνουμε υδρογόνο και οξυγόνο, όχι νερό."}, "status": "new"}, {"id": "L01-valence", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "Valence electrons are the electrons:", "el": "Τα ηλεκτρόνια σθένους είναι τα ηλεκτρόνια:"}, "o": [{"en": "in the outermost shell", "el": "της εξωτερικής στιβάδας"}, {"en": "closest to the nucleus", "el": "που είναι πιο κοντά στον πυρήνα"}, {"en": "inside the nucleus", "el": "μέσα στον πυρήνα"}], "a": 0, "tags": [null, "inner_shell", "nucleus_mixup"], "x": {"en": "The outer shell decides how an atom bonds and whether it conducts.", "el": "Η εξωτερική στιβάδα καθορίζει πώς δεσμεύεται το άτομο και αν άγει."}, "status": "new"}, {"id": "L01-weight", "lesson": "L01", "topic": "3.01", "d": 2, "units": "SI", "q": {"en": "An object of mass 10 kg on Earth (g = 9.81 m/s²) has a weight of about:", "el": "Σώμα μάζας 10 kg στη Γη (g = 9,81 m/s²) έχει βάρος περίπου:"}, "o": [{"en": "10 kg", "el": "10 kg"}, {"en": "98.1 N", "el": "98,1 N"}, {"en": "1.02 N", "el": "1,02 N"}], "a": 1, "tags": ["mass_weight", null, "divided_g"], "x": {"en": "Weight = mass × gravity = 10 × 9.81 = 98.1 N.", "el": "Βάρος = μάζα × g = 10 × 9,81 = 98,1 N."}, "status": "new"}, {"id": "L02-static", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "Static electricity is:", "el": "Ο στατικός ηλεκτρισμός είναι:"}, "o": [{"en": "a build-up of charge on the surface of an object", "el": "συσσώρευση φορτίου στην επιφάνεια ενός σώματος"}, {"en": "a steady flow of electrons in a closed circuit", "el": "σταθερή ροή ηλεκτρονίων σε κλειστό κύκλωμα"}, {"en": "the current produced by a battery", "el": "το ρεύμα που δίνει μια μπαταρία"}], "a": 0, "tags": [null, "static_dynamic", "static_dynamic"], "x": {"en": "Static: charges at rest, piled up on a surface. A flow of electrons is dynamic electricity.", "el": "Στατικός: φορτία σε ηρεμία, συσσωρευμένα σε μια επιφάνεια. Η ροή ηλεκτρονίων είναι δυναμικός ηλεκτρισμός."}, "status": "new"}, {"id": "L02-insulator", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "A static charge builds up when two surfaces touch and separate and at least one of them is:", "el": "Στατικό φορτίο δημιουργείται όταν δύο επιφάνειες έρθουν σε επαφή και απομακρυνθούν, και τουλάχιστον η μία είναι:"}, "o": [{"en": "a conductor", "el": "αγωγός"}, {"en": "an insulator", "el": "μονωτής"}, {"en": "grounded", "el": "γειωμένη"}], "a": 1, "tags": ["conductor_leaks", null, "conductor_leaks"], "x": {"en": "An insulator cannot let the extra charge flow away, so the imbalance stays.", "el": "Ο μονωτής δεν αφήνει το επιπλέον φορτίο να φύγει, οπότε η ανισορροπία παραμένει."}, "status": "new"}, {"id": "L02-tribo", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "In the triboelectric effect, the material that loses electrons becomes:", "el": "Στο τριβοηλεκτρικό φαινόμενο, το υλικό που χάνει ηλεκτρόνια γίνεται:"}, "o": [{"en": "negative", "el": "αρνητικό"}, {"en": "positive", "el": "θετικό"}, {"en": "neutral", "el": "ουδέτερο"}], "a": 1, "tags": ["ion_sign", null, "conservation"], "x": {"en": "Losing negative electrons leaves more protons than electrons: positive.", "el": "Χάνοντας αρνητικά ηλεκτρόνια μένουν περισσότερα πρωτόνια: θετικό."}, "status": "new"}, {"id": "L02-fur", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A plastic rod is rubbed with fur. The plastic becomes negative. The fur becomes:", "el": "Πλαστική ράβδος τρίβεται με γούνα και η ράβδος φορτίζεται αρνητικά. Η γούνα γίνεται:"}, "o": [{"en": "positive, with the same amount of charge", "el": "θετική, με ίσο ποσό φορτίου"}, {"en": "negative as well", "el": "επίσης αρνητική"}, {"en": "neutral", "el": "ουδέτερη"}], "a": 0, "tags": [null, "conservation", "conservation"], "x": {"en": "Charge is conserved: the electrons the plastic gained came from the fur.", "el": "Το φορτίο διατηρείται: τα ηλεκτρόνια που κέρδισε το πλαστικό ήρθαν από τη γούνα."}, "status": "new"}, {"id": "L02-likes", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "Two pith balls touched by the same positively charged glass rod will:", "el": "Δύο σφαιρίδια που ακουμπήθηκαν από την ίδια θετικά φορτισμένη γυάλινη ράβδο θα:"}, "o": [{"en": "attract each other", "el": "έλκονται"}, {"en": "repel each other", "el": "απωθούνται"}, {"en": "not affect each other", "el": "δεν αλληλεπιδρούν"}], "a": 1, "tags": ["like_unlike", null, "like_unlike"], "x": {"en": "Both get the same (positive) charge. Like charges repel.", "el": "Παίρνουν και τα δύο θετικό φορτίο. Ομώνυμα φορτία απωθούνται."}, "status": "new"}, {"id": "L02-fielddir", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "The direction of an electric field line is the direction in which:", "el": "Η φορά μιας δυναμικής γραμμής ηλεκτρικού πεδίου είναι η φορά προς την οποία:"}, "o": [{"en": "an electron would move", "el": "θα κινούνταν ένα ηλεκτρόνιο"}, {"en": "a small positive test charge would move", "el": "θα κινούνταν ένα μικρό θετικό δοκιμαστικό φορτίο"}, {"en": "the field gets weaker", "el": "το πεδίο εξασθενεί"}], "a": 1, "tags": ["test_charge", null, "field_strength"], "x": {"en": "By convention a positive test charge sets the direction: away from + and into −.", "el": "Κατά σύμβαση τη φορά την ορίζει θετικό δοκιμαστικό φορτίο: από το + προς το −."}, "status": "new"}, {"id": "L02-density", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "On a field-line drawing, the strength of the field is shown by:", "el": "Σε ένα σχέδιο δυναμικών γραμμών, η ένταση του πεδίου φαίνεται από:"}, "o": [{"en": "the length of the lines", "el": "το μήκος των γραμμών"}, {"en": "the number of lines per unit area", "el": "τον αριθμό γραμμών ανά μονάδα επιφάνειας"}, {"en": "the direction of the arrowheads", "el": "τη φορά των βελών"}], "a": 1, "tags": ["field_strength", null, "field_strength"], "x": {"en": "Closely spaced lines mean a strong field; arrows only show the direction.", "el": "Πυκνές γραμμές σημαίνουν ισχυρό πεδίο· τα βέλη δείχνουν μόνο τη φορά."}, "status": "new"}, {"id": "L02-hollow", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A hollow metal sphere is charged. The excess charge is found:", "el": "Μια κούφια μεταλλική σφαίρα φορτίζεται. Το επιπλέον φορτίο βρίσκεται:"}, "o": [{"en": "evenly on the inner and outer surfaces", "el": "ομοιόμορφα στην εσωτερική και την εξωτερική επιφάνεια"}, {"en": "only on the outer surface", "el": "μόνο στην εξωτερική επιφάνεια"}, {"en": "only on the inner surface", "el": "μόνο στην εσωτερική επιφάνεια"}], "a": 1, "tags": ["outer_surface", null, "outer_surface"], "x": {"en": "Like charges push as far apart as possible: all of it goes to the outside. The inside is neutral and field-free.", "el": "Τα ομώνυμα φορτία απομακρύνονται όσο γίνεται: όλο το φορτίο πάει έξω. Το εσωτερικό είναι ουδέτερο και χωρίς πεδίο."}, "status": "new"}, {"id": "L02-points", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "On an irregularly shaped charged conductor, the charge is most concentrated:", "el": "Σε αγωγό ακανόνιστου σχήματος, το φορτίο είναι πιο συγκεντρωμένο:"}, "o": [{"en": "on the flattest areas", "el": "στις πιο επίπεδες περιοχές"}, {"en": "at the points and sharp edges", "el": "στις αιχμές και τις οξείες ακμές"}, {"en": "evenly everywhere", "el": "ομοιόμορφα παντού"}], "a": 1, "tags": ["sharp_points", null, "sharp_points"], "x": {"en": "The tighter the curvature, the more charge per area and the stronger the field. That is why static wicks are pointed.", "el": "Όσο πιο έντονη η καμπυλότητα, τόσο περισσότερο φορτίο ανά επιφάνεια και ισχυρότερο πεδίο. Γι' αυτό τα static wicks είναι μυτερά."}, "status": "new"}, {"id": "L02-induction", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A neutral metal bar is charged by induction using a positively charged rod. The bar ends up:", "el": "Μια ουδέτερη μεταλλική ράβδος φορτίζεται με επαγωγή από θετικά φορτισμένη ράβδο. Η ράβδος καταλήγει:"}, "o": [{"en": "positive", "el": "θετική"}, {"en": "negative", "el": "αρνητική"}, {"en": "neutral", "el": "ουδέτερη"}], "a": 1, "tags": ["contact_induction", null, "ground_order"], "x": {"en": "Induction (with grounding) leaves the opposite sign: electrons come in from ground and stay.", "el": "Η επαγωγή (με γείωση) αφήνει το αντίθετο πρόσημο: ηλεκτρόνια έρχονται από τη γη και μένουν."}, "status": "new"}, {"id": "L02-contact", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "A neutral metal bar touched by a positively charged rod becomes:", "el": "Μια ουδέτερη μεταλλική ράβδος που ακουμπά θετικά φορτισμένη ράβδο γίνεται:"}, "o": [{"en": "positive", "el": "θετική"}, {"en": "negative", "el": "αρνητική"}, {"en": "neutral", "el": "ουδέτερη"}], "a": 0, "tags": [null, "contact_induction", "conservation"], "x": {"en": "By contact the bar takes the same sign as the rod: the rod pulls electrons out of it.", "el": "Με επαφή η ράβδος παίρνει το ίδιο πρόσημο: η φορτισμένη ράβδος της αφαιρεί ηλεκτρόνια."}, "status": "new"}, {"id": "L02-coulombunit", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "One coulomb is the charge carried by:", "el": "Ένα coulomb είναι το φορτίο που μεταφέρει:"}, "o": [{"en": "one ampere in one second", "el": "ρεύμα ενός ampere σε ένα δευτερόλεπτο"}, {"en": "one electron", "el": "ένα ηλεκτρόνιο"}, {"en": "one volt across one ohm", "el": "τάση ενός volt σε ένα ohm"}], "a": 0, "tags": [null, "elementary_charge", "ohm_mixup"], "x": {"en": "Q = I × t, so 1 C = 1 A × 1 s.", "el": "Q = I × t, άρα 1 C = 1 A × 1 s."}, "status": "new"}, {"id": "L02-electrons", "lesson": "L02", "topic": "3.02", "d": 2, "units": "SI", "q": {"en": "A current of 2 A flows for 1 s. About how many electrons pass a point?", "el": "Ρεύμα 2 A ρέει για 1 s. Περίπου πόσα ηλεκτρόνια περνούν από ένα σημείο;"}, "o": [{"en": "6.24 × 10¹⁸", "el": "6,24 × 10¹⁸"}, {"en": "1.25 × 10¹⁹", "el": "1,25 × 10¹⁹"}, {"en": "3.2 × 10⁻¹⁹", "el": "3,2 × 10⁻¹⁹"}], "a": 1, "tags": ["forgot_current", null, "inverted_e"], "x": {"en": "Q = 2 A × 1 s = 2 C, and 2 × 6.24 × 10¹⁸ ≈ 1.25 × 10¹⁹ electrons.", "el": "Q = 2 A × 1 s = 2 C, και 2 × 6,24 × 10¹⁸ ≈ 1,25 × 10¹⁹ ηλεκτρόνια."}, "status": "new"}, {"id": "L02-dist2", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "The distance between two point charges is doubled. The force between them:", "el": "Η απόσταση δύο σημειακών φορτίων διπλασιάζεται. Η δύναμη μεταξύ τους:"}, "o": [{"en": "halves", "el": "υποδιπλασιάζεται"}, {"en": "falls to a quarter", "el": "γίνεται το ένα τέταρτο"}, {"en": "doubles", "el": "διπλασιάζεται"}], "a": 1, "tags": ["forgot_square_d", null, "inverse_mixup"], "x": {"en": "F ∝ 1/d²: doubling d divides F by 2² = 4.", "el": "F ∝ 1/d²: διπλάσια απόσταση διαιρεί τη δύναμη με 2² = 4."}, "status": "new"}, {"id": "L02-both2", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "Both charges are doubled and the distance stays the same. The force:", "el": "Διπλασιάζονται και τα δύο φορτία, ενώ η απόσταση μένει ίδια. Η δύναμη:"}, "o": [{"en": "doubles", "el": "διπλασιάζεται"}, {"en": "becomes four times larger", "el": "τετραπλασιάζεται"}, {"en": "stays the same", "el": "μένει ίδια"}], "a": 1, "tags": ["one_charge", null, "inverse_mixup"], "x": {"en": "F ∝ Q₁ × Q₂: 2 × 2 = 4 times larger.", "el": "F ∝ Q₁ × Q₂: 2 × 2 = 4 φορές μεγαλύτερη."}, "status": "new"}, {"id": "L02-dist3", "lesson": "L02", "topic": "3.02", "d": 3, "units": "—", "q": {"en": "Two charges repel with 36 N. The distance between them is tripled. The new force is:", "el": "Δύο φορτία απωθούνται με 36 N. Η απόσταση τριπλασιάζεται. Η νέα δύναμη είναι:"}, "o": [{"en": "12 N", "el": "12 N"}, {"en": "4 N", "el": "4 N"}, {"en": "108 N", "el": "108 N"}], "a": 1, "tags": ["forgot_square_d", null, "inverse_mixup"], "x": {"en": "F ∝ 1/d²: 36 N ÷ 3² = 36 ÷ 9 = 4 N.", "el": "F ∝ 1/d²: 36 N ÷ 3² = 36 ÷ 9 = 4 N."}, "status": "new"}, {"id": "L02-coulombcalc", "lesson": "L02", "topic": "3.02", "d": 3, "units": "SI", "q": {"en": "Two charges of 1 µC each are 0.1 m apart (k = 9 × 10⁹ N·m²/C²). The force between them is:", "el": "Δύο φορτία 1 µC το καθένα απέχουν 0,1 m (k = 9 × 10⁹ N·m²/C²). Η δύναμη μεταξύ τους είναι:"}, "o": [{"en": "0.09 N", "el": "0,09 N"}, {"en": "0.9 N", "el": "0,9 N"}, {"en": "9 N", "el": "9 N"}], "a": 1, "tags": ["forgot_square_d", null, "prefix_error"], "x": {"en": "F = 9 × 10⁹ × (10⁻⁶ × 10⁻⁶) / 0.1² = 9 × 10⁻³ / 10⁻² = 0.9 N.", "el": "F = 9 × 10⁹ × (10⁻⁶ × 10⁻⁶) / 0,1² = 9 × 10⁻³ / 10⁻² = 0,9 N."}, "status": "new"}, {"id": "L02-esd", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "Before handling an ESD-sensitive circuit card, a technician should:", "el": "Πριν πιάσει μια κάρτα ευαίσθητη σε ESD, ο τεχνικός πρέπει:"}, "o": [{"en": "wear a grounding wrist strap", "el": "να φορέσει γειωμένο βραχιόλι (wrist strap)"}, {"en": "touch the connector pins to discharge them", "el": "να ακουμπήσει τις ακίδες του connector για να τις εκφορτίσει"}, {"en": "place it on a carpet-covered toolbox", "el": "να την ακουμπήσει σε εργαλειοθήκη με μοκέτα"}], "a": 0, "tags": [null, "esd_pins", "esd_carpet"], "x": {"en": "The strap keeps your body at ground potential, so no discharge goes through the card.", "el": "Το βραχιόλι κρατά το σώμα στο δυναμικό της γης, οπότε δεν περνά εκφόρτιση από την κάρτα."}, "status": "new"}, {"id": "L02-ohmmeter", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "When testing transistors, ohmmeter ranges should not be used if they drive more than:", "el": "Στον έλεγχο τρανζίστορ δεν χρησιμοποιούνται κλίμακες ωμομέτρου που δίνουν ρεύμα πάνω από:"}, "o": [{"en": "1 mA", "el": "1 mA"}, {"en": "1 A", "el": "1 A"}, {"en": "1 µA", "el": "1 µA"}], "a": 0, "tags": [null, "prefix_error", "prefix_error"], "x": {"en": "The precaution in the course: no ohmmeter range above 1 mA on a transistor.", "el": "Η προφύλαξη του μαθήματος: όχι κλίμακα ωμομέτρου πάνω από 1 mA σε τρανζίστορ."}, "status": "new"}, {"id": "L02-refuel", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "Before refuelling, the aircraft and the fuel truck are bonded and grounded because:", "el": "Πριν τον ανεφοδιασμό, το αεροσκάφος και το βυτιοφόρο συνδέονται (bonding) και γειώνονται επειδή:"}, "o": [{"en": "flowing fuel builds up static charge that could spark", "el": "η ροή καυσίμου δημιουργεί στατικό φορτίο που μπορεί να δώσει σπινθήρα"}, {"en": "fuel is a good conductor", "el": "το καύσιμο είναι καλός αγωγός"}, {"en": "the pumps need a return path for their current", "el": "οι αντλίες χρειάζονται δρόμο επιστροφής ρεύματος"}], "a": 0, "tags": [null, "fuel_conductor", "static_dynamic"], "x": {"en": "Fuel is a poor conductor, so flow through hoses and filters builds up charge. Bonding keeps everything at the same potential.", "el": "Το καύσιμο είναι κακός αγωγός, οπότε η ροή σε σωλήνες και φίλτρα φορτίζει. Το bonding κρατά τα πάντα στο ίδιο δυναμικό."}, "status": "new"}, {"id": "L02-liquids", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "In a conducting liquid such as salt water, the current is carried by:", "el": "Σε αγώγιμο υγρό, όπως το αλατόνερο, το ρεύμα μεταφέρεται από:"}, "o": [{"en": "free electrons only", "el": "μόνο ελεύθερα ηλεκτρόνια"}, {"en": "positive and negative ions", "el": "θετικά και αρνητικά ιόντα"}, {"en": "protons only", "el": "μόνο πρωτόνια"}], "a": 1, "tags": ["metal_liquid", null, "nucleus_carrier"], "x": {"en": "In electrolytes both kinds of ions move. Only in metals are free electrons the carriers.", "el": "Στους ηλεκτρολύτες κινούνται και τα δύο είδη ιόντων. Μόνο στα μέταλλα φορείς είναι τα ελεύθερα ηλεκτρόνια."}, "status": "new"}, {"id": "L02-gas", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A gas normally behaves as:", "el": "Ένα αέριο κανονικά συμπεριφέρεται ως:"}, "o": [{"en": "a good conductor", "el": "καλός αγωγός"}, {"en": "an insulator, until a strong field ionizes it", "el": "μονωτής, μέχρι να το ιονίσει ισχυρό πεδίο"}, {"en": "a semiconductor", "el": "ημιαγωγός"}], "a": 1, "tags": ["gas_conductor", null, "gas_conductor"], "x": {"en": "Gases have almost no free carriers. A strong field ionizes them: sparks, lightning, neon lamps.", "el": "Τα αέρια δεν έχουν σχεδόν ελεύθερους φορείς. Ισχυρό πεδίο τα ιονίζει: σπινθήρες, κεραυνοί, λάμπες νέον."}, "status": "new"}, {"id": "L02-vacuum", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A vacuum can carry a current only if:", "el": "Το κενό μπορεί να άγει ρεύμα μόνο αν:"}, "o": [{"en": "electrons are injected into it, e.g. from a heated cathode", "el": "εισαχθούν ηλεκτρόνια, π.χ. από θερμαινόμενη κάθοδο"}, {"en": "it is ionized", "el": "ιονιστεί"}, {"en": "it is cooled", "el": "ψυχθεί"}], "a": 0, "tags": [null, "vacuum_ions", "vacuum_ions"], "x": {"en": "A vacuum has no carriers of its own. Electrons put into it move freely (vacuum tubes, CRTs).", "el": "Το κενό δεν έχει δικούς του φορείς. Ηλεκτρόνια που εισάγονται κινούνται ελεύθερα (λυχνίες κενού, CRT)."}, "status": "new"}]};
